67	        try {
68	            return OwnerTelephone.toE164(telephone);
69	        }
70	        catch (InvalidTelephoneException ex) {
71	            // A value that cannot form a valid E.164 number cannot collide with one that can;
72	            // represent it by its raw form (or empty when absent) so comparison stays total.
73	            return telephone == null ? "" : telephone;
74	        }
75	    }
