5	/**
6	 * Derives an owner's numeric {@code membershipLevel} from the owner's state as fixed at creation.
7	 *
8	 * <p>The level starts at 1 and is incremented by the owner's standing:
9	 *
10	 * <ul>
11	 *   <li>+1 when the owner has a non-blank email;</li>
12	 *   <li>+1 when the owner has no namesakes ({@code namesakeCount == 0}).</li>
13	 * </ul>
14	 *
15	 * <p>The result is capped at 3. Level 4 is reserved for tenure and is not assigned here.
16	 */
17	public final class MembershipLevels {
18	
19	    private MembershipLevels() {
20	    }
21	
22	    public static int levelFor(Owner owner) {
23	        int level = 1;
24	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
25	            level++;
26	        }
27	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
28	            level++;
29	        }
30	        return Math.min(level, 3);
31	    }
32	}
